def transform(grid):
    out = [row[:] for row in grid]
    # Copy each nonzero seed along its row/column into adjacent blank cells,
    # bounded by the 5-colored partition lines.
    h, w = len(grid), len(grid[0])
    # left region: colored values at column 0 extend across to the 5-line gap
    for r in range(h):
        if grid[r][0] not in (0, 5):
            for c in range(1, 5):
                out[r][c] = grid[r][0]
    # right region: horizontal seed patterns in bottom rows repeat upward
    seeds = [r for r in range(h) if all(grid[r][c] != 0 for c in range(7, 10))]
    if seeds:
        for r in range(1, max(seeds)):
            # repeat the observed bottom-row cycle, extending in reverse from its start
            source = seeds[(r - seeds[0]) % len(seeds)]
            for c in range(7, 10):
                out[r][c] = grid[source][c]
    return out
